import{_ as t,c as a,o,ae as s}from"./chunks/framework.Bi6zybwU.js";const u=JSON.parse('{"title":"Advanced Shortcode","description":"Advanced Shortcode","frontmatter":{"title":"Advanced Shortcode","description":"Advanced Shortcode"},"headers":[],"relativePath":"guide/advanced-features/advanced-shortcode.md","filePath":"guide/advanced-features/advanced-shortcode.md"}'),r={name:"guide/advanced-features/advanced-shortcode.md"};function l(n,e,d,i,c,h){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="advanced-shortcode" tabindex="-1">Advanced Shortcode <a class="header-anchor" href="#advanced-shortcode" aria-label="Permalink to &quot;Advanced Shortcode&quot;">​</a></h1><p>You can apply an Advanced Shortcode to the Ninja Tables whenever needed.</p><h2 id="basic-usage" tabindex="-1">Basic Usage <a class="header-anchor" href="#basic-usage" aria-label="Permalink to &quot;Basic Usage&quot;">​</a></h2><p>You can use the shortcodes given below according to your needs:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[ninja_tables id=&#39;YOUR TABLE ID HERE&#39;]</span></span></code></pre></div><h2 id="advanced-usage-of-ninja-tables-shortcode" tabindex="-1">Advanced Usage of Ninja Tables Shortcode <a class="header-anchor" href="#advanced-usage-of-ninja-tables-shortcode" aria-label="Permalink to &quot;Advanced Usage of Ninja Tables Shortcode&quot;">​</a></h2><p>A set of highly useful shortcodes is provided by <strong>Ninja Tables,</strong> where you can configure the features in the shortcode so that you can display the same table on a separate page/post in a different manner.</p><p><strong>Accessible Shortcode Parameters</strong></p><table tabindex="0"><thead><tr><th><strong>Shortcode Parameter</strong></th><th><strong>Description</strong></th></tr></thead><tbody><tr><td>per_page</td><td>You can specify how many rows will show in ninja tables per page. <strong>Value Type:</strong> Number</td></tr><tr><td>Search</td><td>You can enable or disable the search bar. <strong>Possible Value:</strong> 0 or 1</td></tr><tr><td>sorting</td><td>You can enable/disable data sorting features. <strong>Possible Value:</strong> 0 or 1</td></tr><tr><td>hide_header</td><td>You can show/hide the header row. <strong>Possible Value:</strong> 0 or 1</td></tr><tr><td>logged_in_only</td><td>You can show a table only for logged-in users. <strong>Value:</strong> 0 or 1 (if value = 1 then the table can be visible only for logged-in users)</td></tr><tr><td>get_filter</td><td>You can set search filter from URL&#39;s get parameter. Provide the filter name and then Ninja Table will filter the table data from your browser&#39;s get parameter</td></tr><tr><td>filter</td><td>You can add the filter parameter as a pre-defined search value for the table</td></tr><tr><td>filter_column</td><td>You can specify in which column the &quot;filter&quot; will be applied. You have to provide the column key</td></tr><tr><td>hide_default_filter</td><td>If you use a filter parameter and want don&#39;t want to show hidden values even after resetting the filter in frontend then you can set this value as <strong>&#39;yes&#39;</strong></td></tr><tr><td>columns</td><td>You can specify which columns key will show. Just specify the column keys as comma-separated values then those columns will show only.</td></tr><tr><td>filter_selects</td><td>If you use custom filters UI for your table and you can set pre-defined values for the select elements. Basic Usage: <code>filter_selects=&#39;FILTER_TITLE=defaultValue&#39;</code>. If you want to add multiple pre-defined selected values you can do that like this: <code>filter_selects=&#39;FILTER_TITLE_1=defaultValue1|FILTER_TITLE_2=defaultValue2&#39;</code></td></tr><tr><td>limit</td><td>If you want to limit the data then you use this parameter. Example: <code>limit=&#39;20&#39;</code>. It will show only 20 rows from your table&#39;s data source.</td></tr><tr><td>skip</td><td>If you want to skip a few rows from your table&#39;s data source then you use this parameter. Example: <code>skip=&#39;10&#39;</code>. It will skip the first 10 rows from your table&#39;s data source.</td></tr><tr><td>info</td><td>This parameter lets you show the table meta info after pagination. Example: <code>info=&#39;Current Page {CP} of {TP}&#39;</code>. Placeholders: {CP} - The current page. {TP} - The total number of pages available. {PF} - The first-row number of the current page. <strong>{PL}</strong> - The last row number of the current page. <strong>{TR}</strong> - The total number of rows available.</td></tr></tbody></table><h2 id="examples-of-shortcodes" tabindex="-1"><strong>Examples of Shortcodes</strong> <a class="header-anchor" href="#examples-of-shortcodes" aria-label="Permalink to &quot;**Examples of Shortcodes**&quot;">​</a></h2><p><a href="https://gist.github.com/techjewel/55703124534f1aba9b70cf0f605a793e" target="_blank" rel="noreferrer">https://gist.github.com/techjewel/55703124534f1aba9b70cf0f605a793e</a></p><p><strong>Please Note that Advanced Shortcode is available only in the Pro Version of Ninja Tables</strong></p><h3 id="date-range-filter-shortcode" tabindex="-1">Date range filter- shortcode <a class="header-anchor" href="#date-range-filter-shortcode" aria-label="Permalink to &quot;Date range filter- shortcode&quot;">​</a></h3><p>Suppose you wish to primarily filter the date or date range if you have a table with a date column. This option is available in <strong>NinjaTables version 3.5.8</strong>. Use the date range filter with shortcode after upgrading your plugin to the latest version.</p><p><img src="https://ninjatables.com/wp-content/uploads/2023/10/Advanced-shortcode-1024x307.png" alt="Advanced shortcode"></p><p><strong>To filter by date range:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>filter=&quot;~{date:M/D/YYYY}:{date:M/D/YYYY}&quot;   filter_column=&quot;date&quot;</span></span></code></pre></div><p><strong>To filter the date before 7 days to the next 1 day:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>filter=&quot;~{date-7:M/D/YYYY}:{date+1:M/D/YYYY}&quot;  filter_column=&quot;date&quot;</span></span></code></pre></div><p><strong>For greater than use:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>filter=&quot;{gt}{date:M/D/YYYY}&quot;</span></span></code></pre></div><p><strong>For Less Than use:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>filter=&quot;{lt}{date:M/D/YYYY}&quot;</span></span></code></pre></div><p>Use this on your shortcode. The shortcode filter column is used to choose the column you want to filter.</p><p>NB: The date format must be the same as the date format for the columns.</p><h3 id="other-shortcodes-table-info" tabindex="-1">Other Shortcodes - Table Info <a class="header-anchor" href="#other-shortcodes-table-info" aria-label="Permalink to &quot;Other Shortcodes - Table Info&quot;">​</a></h3><p>Helper shortcode for ninja tables helps you to easily show the following information.</p><ul><li>title</li><li>description</li><li>total_rows // Will work only for the default table</li><li>last_modified</li><li>last_editor</li></ul><p><strong>Usage:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[ninja_table_info id=&#39;YOUR TABLE ID HERE&#39; field=&quot;INFO_FIELD&quot;]</span></span></code></pre></div><p><strong>The following parameter can be used for field:</strong></p><ul><li>title</li><li>description</li><li>total_rows</li><li>last_modified</li><li>last_editor</li></ul><h3 id="table-cell-info" tabindex="-1">Table Cell Info <a class="header-anchor" href="#table-cell-info" aria-label="Permalink to &quot;Table Cell Info&quot;">​</a></h3><p>There are helper shortcodes where you can display your table cell data for a specific table.</p><p><strong>Usage:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[ninja_table_cell id=&#39;YOUR TABLE ID HERE&#39; row_id=&quot;YOUR_ROW_INDEX&quot; column=&quot;YOUR_COLUMN_KEY&quot;]</span></span></code></pre></div><p>You will get the ROWID for default data source tables. But if you have a table with external data source or wp-posts / csv integration then your shortcode should look like this:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[ninja_table_cell id=&#39;YOUR TABLE ID HERE&#39; row=&quot;YourROWID&quot; column=&quot;YOUR_COLUMN_KEY&quot;]</span></span></code></pre></div><p>This shortcode will print out data from that particular cell data.</p><p>For the Row Index Number you have to click on this icon:</p><p><img src="https://ninjatables.com/wp-content/uploads/2023/01/advanced-shortcode-2.webp" alt="advanced shortcode in table"></p><p>Above here for external data source table, the RowID would be the serial number of the table row</p>',42)])])}const g=t(r,[["render",l]]);export{u as __pageData,g as default};
